import React, { useState, useEffect } from 'react';
import {
  FaUsers, FaProjectDiagram, FaUserCheck, FaBell,
  FaCalendarAlt, FaBug, FaChartLine, FaClock, FaMoneyBill
} from 'react-icons/fa';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  LineChart, Line
} from 'recharts';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import axios from "../Https/Axios";
import './Dashboard.css';
import Particles from 'react-tsparticles';
import { loadSlim } from 'tsparticles-slim';

const Dashboard = () => {
  const [totalEmployees, setTotalEmployees] = useState(0);
  const [activeProjects, setActiveProjects] = useState(0);
  const [attendanceCount, setAttendanceCount] = useState(0);
  const [date, setDate] = useState(new Date());
  const [tasks, setTasks] = useState([]);
  const [newTask, setNewTask] = useState('');
  const [weather, setWeather] = useState(null);
  const [showNotifications, setShowNotifications] = useState(false);

  const recentNotifications = [
    '📅 Project Alpha deadline extended',
    '📢 New company policy update',
    '👥 Team meeting at 4 PM',
  ];

  const revenueData = [
    { month: 'Jan', revenue: 10000 },
    { month: 'Feb', revenue: 12000 },
    { month: 'Mar', revenue: 15000 },
    { month: 'Apr', revenue: 18000 },
    { month: 'May', revenue: 18500 },
  ];

  const monthlyRevenue = 18500;
  const performanceRating = 4.3;
  const projectCompletion = 76;

  const particlesInit = async (engine) => {
    await loadSlim(engine);
  };

  useEffect(() => {
    const fetchDashboardCounts = async () => {
      try {
        const [empRes, projRes, attRes] = await Promise.all([
          axios.get('/api/employees'),
          axios.get('/api/Projects'),
          axios.get('/api/attendances/all'),
        ]);

        setTotalEmployees(empRes.data.length || 0);
        setActiveProjects(projRes.data.length || 0);
        setAttendanceCount(attRes.data.length || 0);
      } catch (err) {
        console.error('API fetch error:', err);
      }
    };

    const fetchWeather = async () => {
      try {
        const res = await axios.get(
          `https://api.open-meteo.com/v1/forecast?latitude=24.8607&longitude=67.0011&current_weather=true`
        );
        setWeather(res.data.current_weather);
      } catch (err) {
        console.error('Weather fetch error:', err);
      }
    };

    fetchDashboardCounts();
    fetchWeather();
  }, []);

  const addTask = () => {
    if (newTask.trim()) {
      setTasks([...tasks, newTask.trim()]);
      setNewTask('');
    }
  };

  const removeTask = (index) => {
    const updated = [...tasks];
    updated.splice(index, 1);
    setTasks(updated);
  };
  const handleLogout = () => {
  // Clear localStorage ya token agar use kar rahe hain
  localStorage.removeItem('token'); // agar token store kar rahe ho
  localStorage.clear();

  // Redirect user to login page
  window.location.href = '/login'; // ya '/' based on your routes
};


  return (
    
    <div className="dashboard-page">
      <div className="logout-container">
  <button className="logout-button" onClick={handleLogout}>🚪 Logout</button>
</div>

      <Particles
        className="particles"
        id="tsparticles-dashboard"
        init={particlesInit}
        options={{
          background: { color: { value: 'transparent' } },
          fpsLimit: 60,
          particles: {
            color: { value: ['#6a0572', '#a83279', '#4b0082', '#7b2cbf', '#3c1053'] },
            links: {
              color: '#6a0572',
              distance: 120,
              enable: true,
              opacity: 0.6,
              width: 1.4,
            },
            move: { enable: true, speed: 0.8 },
            number: { value: 60 },
            opacity: { value: 0.6 },
            shape: { type: 'circle' },
            size: { value: { min: 2, max: 5 } },
          },
          interactivity: {
            events: { onHover: { enable: true, mode: 'repulse' } },
            modes: { repulse: { distance: 100, duration: 0.4 } },
          },
          detectRetina: true,
        }}
      />

      <div className="dashboard-wrapper">
        <main className="dashboard-main">
          <div className="dashboard-header">
            <h1 className="dashboard-title">✨ Dashboard Overview</h1>
            <button className="bell-icon" onClick={() => setShowNotifications(!showNotifications)}>
              <FaBell />
            </button>
          </div>

          {showNotifications && (
            <div className="notifications-dropdown">
              <h3>🔔 Notifications</h3>
              <ul>
                {recentNotifications.map((note, index) => (
                  <li key={index}>{note}</li>
                ))}
              </ul>
            </div>
          )}

          <div className="dashboard-content-grid">
            <div className="left-column">
              <div className="cards-container">
                <div className="card animated-card">
                  <FaUsers className="card-icon" />
                  <h3>Total Employees</h3>
                  <p><strong>{totalEmployees}</strong></p>
                </div>
                <div className="card animated-card">
                  <FaProjectDiagram className="card-icon" />
                  <h3>Total Projects</h3>
                  <p><strong>{activeProjects}</strong></p>
                </div>
                <div className="card animated-card">
                  <FaUserCheck className="card-icon" />
                  <h3>Attendances</h3>
                  <p><strong>{attendanceCount}</strong></p>
                </div>
                <div className="card animated-card">
                  <FaMoneyBill className="card-icon" />
                  <h3>Monthly Revenue</h3>
                  <p>${monthlyRevenue.toLocaleString()}</p>
                </div>
                <div className="card animated-card">
                  <FaChartLine className="card-icon" />
                  <h3>Performance Rating</h3>
                  <p>{performanceRating} / 5 ⭐</p>
                </div>
                <div className="card animated-card">
                  <FaChartLine className="card-icon" />
                  <h3>Project Completion</h3>
                  <p>{projectCompletion}% done</p>
                </div>
              </div>

              <div className="graphs-container">
                <div className="graph-card">
                  <h3>Monthly Revenue</h3>
                  <ResponsiveContainer width="100%" height={250}>
                    <LineChart data={revenueData}>
                      <XAxis dataKey="month" />
                      <YAxis />
                      <CartesianGrid strokeDasharray="3 3" />
                      <Tooltip />
                      <Line type="monotone" dataKey="revenue" stroke="#5f27cd" strokeWidth={3} />
                    </LineChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>

            <div className="right-widgets">
              <div className="widget-card glassy">
                <h3>📅 Calendar</h3>
                <Calendar onChange={setDate} value={date} />
                <p className="selected-date">Selected: {date.toDateString()}</p>
              </div>

              <div className="widget-card glassy">
                <h3>✅ Task Tracker</h3>
                <div className="task-input">
                  <input
                    type="text"
                    value={newTask}
                    onChange={(e) => setNewTask(e.target.value)}
                    placeholder="Add a new task..."
                  />
                  <button onClick={addTask}>➕</button>
                </div>
                <ul className="task-list">
                  {tasks.map((task, i) => (
                    <li key={i}>
                      {task} <button onClick={() => removeTask(i)}>❌</button>
                    </li>
                  ))}
                </ul>
              </div>

              <div className="widget-card glassy">
                <h3>🌤️ Weather (Karachi)</h3>
                {weather ? (
                  <div>
                    <p>🌡 Temp: {weather.temperature}°C</p>
                    <p>💨 Wind: {weather.windspeed} km/h</p>
                    <p>⏳ Time: {weather.time.split('T')[1].slice(0, 5)}</p>
                  </div>
                ) : (
                  <p>Loading weather...</p>
                )}
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default Dashboard;