import React, { useState, useEffect } from 'react';
import axios from "../Https/Axios";
import { FiEdit, FiTrash2, FiPlus, FiRefreshCw } from 'react-icons/fi';
import './Employee.css';
import Particles from 'react-tsparticles';
import { loadSlim } from 'tsparticles-slim';

const Employee = () => {
  const [employees, setEmployees] = useState([]);
  const [modalData, setModalData] = useState(null);
  const [resettingId, setResettingId] = useState(null);

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      const res = await axios.get('/api/employees');
      const formatted = res.data.map((emp) => ({
        id: emp._id,
        name: emp.name,
        department: emp.department,
        role: emp.role,
        email: emp.email,
        password: emp.password,
        isBlocked: emp.isBlocked || false,
      }));
      setEmployees(formatted);
    } catch (error) {
      console.error('Failed to fetch employees:', error);
    }
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`/api/employees/${id}`);
      setEmployees((prev) => prev.filter((emp) => emp.id !== id));
    } catch (error) {
      console.error('Failed to delete employee:', error);
    }
  };

  const handleToggleBlock = (id) => {
    setEmployees((prev) =>
      prev.map((emp) =>
        emp.id === id ? { ...emp, isBlocked: !emp.isBlocked } : emp
      )
    );
  };

  const handleEdit = (emp) => {
    setModalData(emp);
  };

  const handleAdd = () => {
    setModalData({});
  };

  const handleSave = async (e) => {
    e.preventDefault();
    const form = e.target;
    const employeeData = {
      name: form.name.value,
      email: form.email.value,
      password: form.password.value,
      role: form.role.value,
      department: form.department.value,
      isBlocked: modalData.isBlocked || false,
    };

    try {
      if (modalData.id) {
        await axios.put(`/api/employees/${modalData.id}`, employeeData);
      } else {
        await axios.post('/api/employees', employeeData);
        alert('Employee added successfully!');
      }
      setModalData(null);
      fetchEmployees();
    } catch (error) {
      console.error('Failed to save employee:', error);
    }
  };

  const handleResetPassword = (id) => {
    setResettingId(id);
  };

  const confirmResetPassword = () => {
    alert('Password reset link sent to employee email!');
    setResettingId(null);
  };

  const cancelResetPassword = () => {
    setResettingId(null);
  };

  const particlesInit = async (engine) => {
    await loadSlim(engine);
  };

  return (
    <div className="manage-container">
      <Particles
        className="particles"
        id="tsparticles"
        init={particlesInit}
        options={{
          background: { color: { value: 'transparent' } },
          fpsLimit: 60,
          particles: {
            color: { value: ['#6a0572', '#a83279', '#4b0082', '#7b2cbf', '#3c1053'] },
            links: { color: '#6a0572', distance: 120, enable: true, opacity: 0.6, width: 1.4 },
            move: { enable: true, speed: 0.8 },
            number: { value: 60 },
            opacity: { value: 0.6 },
            shape: { type: 'circle' },
            size: { value: { min: 2, max: 5 } },
          },
          interactivity: {
            events: { onHover: { enable: true, mode: 'repulse' } },
            modes: { repulse: { distance: 100, duration: 0.4 } },
          },
          detectRetina: true,
        }}
      />

      <div className="content">
        <div className="header">
          <h2>Manage Employees</h2>
          <button className="add-btn" onClick={handleAdd}>
            <FiPlus /> Add Employee
          </button>
        </div>

        <table className="employee-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Pass</th>
              <th>Department</th>
              <th>Role</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {employees.map((emp) => (
              <tr key={emp.id} className={emp.isBlocked ? 'blocked' : ''}>
                <td data-label="Name">{emp.name}</td>
                <td data-label="Email">{emp.email}</td>
                <td data-label="Pass">{emp.password}</td>
                <td data-label="Department">{emp.department}</td>
                <td data-label="Role">
                  <span className={`role-badge role-${emp.role.replace(/\s/g, '').toLowerCase()}`}>
                    {emp.role}
                  </span>
                </td>
                <td data-label="Status">
                  <label className="switch" title={emp.isBlocked ? 'Blocked' : 'Active'}>
                    <input
                      type="checkbox"
                      checked={!emp.isBlocked}
                      onChange={() => handleToggleBlock(emp.id)}
                    />
                    <span className="slider round"></span>
                  </label>
                </td>
                <td data-label="Actions">
                  <div className="actions">
                    <button onClick={() => handleEdit(emp)} title="Edit"><FiEdit /></button>
                    <button onClick={() => handleDelete(emp.id)} title="Delete"><FiTrash2 /></button>
                    <button onClick={() => handleResetPassword(emp.id)} title="Reset Password" className="reset-btn"><FiRefreshCw /></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {modalData !== null && (
          <div className="modal-overlay">
            <div className="modal">
              <h3>{modalData.id ? 'Edit Employee' : 'Add Employee'}</h3>
              <form onSubmit={handleSave}>
                <input name="name" defaultValue={modalData.name} placeholder="Name" required autoFocus />
                <input name="email" defaultValue={modalData.email} placeholder="Email" required />
                
                <small style={{ fontSize: '12px', color: '#777' }}>
                  Add minimum 6 characters
                </small>
                <input
                  name="password"
                  defaultValue={modalData.password}
                  placeholder="Password"
                  required
                  minLength={6}
                />

                <select name="role" defaultValue={modalData.role || ''} required>
                  <option value="" disabled>Select Role</option>
                  <option value="intern">Intern</option>
                  <option value="team_lead">Team Lead</option>
                  <option value="employee">Employee</option>
                </select>

                <input name="department" defaultValue={modalData.department} placeholder="Department" required />

                <button type="submit">Save</button>
                <button type="button" className="cancel" onClick={() => setModalData(null)}>Cancel</button>
              </form>
            </div>
          </div>
        )}

        {resettingId !== null && (
          <div className="modal-overlay">
            <div className="modal">
              <h3>Reset Password</h3>
              <p>Are you sure you want to send a password reset link?</p>
              <button onClick={confirmResetPassword}>Confirm</button>
              <button className="cancel" onClick={cancelResetPassword}>Cancel</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Employee;
