import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Employee from './components/Employee';
import Projects from './components/Projects';
import Attendance from './components/Attendance';
import Notifications from './components/Notifications';
import LoginForm from './components/LoginForm';
import LeaveManagement from './components/LeaveManagement';
import Reports from './components/Reports';
import ProblemReports from './components/ProblemReports';

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const sidebarWidth = '240px';
  const [isWideScreen, setIsWideScreen] = useState(window.innerWidth > 840);

  // ✅ Token check on page load
  useEffect(() => {
    const token = localStorage.getItem('admintokenems');
    if (token) {
      setIsLoggedIn(true);
    }
  }, []);

  // ✅ Responsive sidebar logic
  useEffect(() => {
    const handleResize = () => setIsWideScreen(window.innerWidth > 840);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // ✅ On successful login
  const handleLoginSuccess = () => {
    setIsLoggedIn(true);
  };

  // ✅ Logout handler
  const handleLogout = () => {
    localStorage.removeItem('admintokenems');
    setIsLoggedIn(false);
  };

  // ✅ Protected layout with sidebar and routes
  const ProtectedLayout = () => (
  <div style={{ display: isWideScreen ? 'block' : 'flex' }}>
    <div
      style={{
        position: isWideScreen ? 'fixed' : 'relative',
        top: 0,
        left: 0,
        height: isWideScreen ? '100vh' : 'auto',
        backgroundColor: '#1e1e2f',
        zIndex: 1000,
      }}
    >
      <Sidebar onLogout={handleLogout} />
    </div>

    <div
      style={{
        width: isWideScreen ? `calc(100% - ${sidebarWidth})` : '100%',
        marginLeft: isWideScreen ? sidebarWidth : '0px',
      }}
    >
      {/* ✅ Wrap all routes inside <Routes> */}
      <Routes>
        <Route path="/dashboard" element={<Dashboard />} />
        <Route path="/employee" element={<Employee />} />
        <Route path="/projects" element={<Projects />} />
        <Route path="/attendance" element={<Attendance />} />
        <Route path="/notifications" element={<Notifications />} />
        <Route path="/leavemanagement" element={<LeaveManagement />} />
        <Route path="/reports" element={<Reports />} />
        <Route path="/problemreports" element={<ProblemReports />} />
        <Route path="*" element={<Navigate to="/dashboard" />} />
      </Routes>
    </div>
  </div>
);


  return (
    <>
      {isLoggedIn ? (
        <ProtectedLayout />
      ) : (
        <Routes>
          <Route path="/login" element={<LoginForm onSuccess={handleLoginSuccess} />} />
          <Route path="*" element={<Navigate to="/login" />} />
        </Routes>
      )}
    </>
  );
};

export default App;
