import React, { useState } from 'react';
import './LoginForm.css';
import { FaUser, FaLock, FaEye, FaEyeSlash } from 'react-icons/fa';
import Particles from 'react-tsparticles';
import { loadSlim } from 'tsparticles-slim';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const LoginForm = ({ onSuccess }) => {  // ✅ Accept onSuccess as prop
  const [showPassword, setShowPassword] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const togglePassword = () => setShowPassword(!showPassword);

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await axios.post('https://emsbackend-two.vercel.app/api/admin/login', {
        email,
        password,
      });

      alert('Login successful!');
      localStorage.setItem('admintokenems', response.data.token);

      if (onSuccess) onSuccess(); // ✅ Inform App.js about login
      navigate('/dashboard');

    } catch (error) {
      alert('Error: ' + (error.response?.data?.message || 'Server error'));
    }
  };

  const particlesInit = async (engine) => {
    await loadSlim(engine);
  };

  return (
    <div className="login-page">
      <Particles
        className="particles"
        id="tsparticles"
        init={particlesInit}
        options={{
          background: { color: { value: 'transparent' } },
          fpsLimit: 60,
          particles: {
            color: {
              value: ['#6a0572', '#a83279', '#4b0082', '#7b2cbf', '#3c1053'],
            },
            links: {
              color: '#6a0572',
              distance: 120,
              enable: true,
              opacity: 0.6,
              width: 1.4,
            },
            move: { enable: true, speed: 0.8 },
            number: { value: 60 },
            opacity: { value: 0.6 },
            shape: { type: 'circle' },
            size: { value: { min: 2, max: 5 } },
          },
          interactivity: {
            events: {
              onHover: { enable: true, mode: 'repulse' },
            },
            modes: {
              repulse: { distance: 100, duration: 0.4 },
            },
          },
          detectRetina: true,
        }}
      />

      <div className="login-container">
        <form className="login-form" onSubmit={handleSubmit}>
          <h2 className="login-title">Welcome Back</h2>

          <div className="input-group">
            <FaUser className="input-icon" />
            <input
              type="email"
              placeholder="Email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>

          <div className="input-group">
            <FaLock className="input-icon" />
            <input
              type={showPassword ? 'text' : 'password'}
              placeholder="Password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <span className="toggle-password" onClick={togglePassword}>
              {showPassword ? <FaEyeSlash /> : <FaEye />}
            </span>
          </div>

          <button className="login-button" type="submit">
            Login
          </button>
        </form>
      </div>
    </div>
  );
};

export default LoginForm;
