import React, { useEffect, useState } from "react";
import axios from "../Https/Axios";
import "./Notifications.css";
import Modal from "react-modal";
import {
  FaCheckCircle,
  FaExclamationTriangle,
  FaInfoCircle,
  FaBell,
  FaEdit,
  FaTrash,
} from "react-icons/fa";
import Particles from "react-tsparticles";
import { loadSlim } from "tsparticles-slim";

Modal.setAppElement("#root");

const particlesInit = async (engine) => {
  await loadSlim(engine);
};

const getIcon = (type) => {
  switch (type) {
    case "info":
      return <FaInfoCircle className="icon info" />;
    case "alert":
      return <FaExclamationTriangle className="icon alert" />;
    case "success":
      return <FaCheckCircle className="icon success" />;
    default:
      return <FaBell className="icon default" />;
  }
};

const Notifications = () => {
  const [notifications, setNotifications] = useState([]);
  const [selected, setSelected] = useState(null);
  const [filter, setFilter] = useState("all");
  const [newTitle, setNewTitle] = useState("");
  const [newMessage, setNewMessage] = useState("");
  const [recipient, setRecipient] = useState("all");
  const [loading, setLoading] = useState(false);
  const [employees, setEmployees] = useState([]);
  const [editId, setEditId] = useState(null);

  useEffect(() => {
    fetchNotifications();
    fetchEmployees();
  }, []);

  const fetchNotifications = async () => {
    setLoading(true);
    try {
      const res = await axios.get("/api/notifications");
      const mapped = res.data.map((notif) => ({
        id: notif._id,
        type: "info",
        title: notif.title,
        message: notif.message,
        time: new Date(notif.createdAt).toLocaleString(),
        read: false,
        recipients: notif.recipients,
      }));
      setNotifications(mapped);
    } catch (err) {
      console.error("Error fetching notifications:", err);
    }
    setLoading(false);
  };

  const fetchEmployees = async () => {
    try {
      const res = await axios.get("/api/employees");
      setEmployees(res.data);
    } catch (err) {
      console.error("Error fetching employees:", err);
    }
  };

  const addNotification = async () => {
    if (newTitle.trim() === "" || newMessage.trim() === "") return;

    const notifData = {
      title: newTitle,
      message: newMessage,
      recipients: recipient === "all" ? [] : [recipient],
    };

    try {
      if (editId) {
        const res = await axios.put(`/api/notifications/${editId}`, notifData);
        setNotifications((prev) =>
          prev.map((n) =>
            n.id === editId
              ? {
                  ...n,
                  title: res.data.title,
                  message: res.data.message,
                  recipients: res.data.recipients,
                }
              : n
          )
        );
      } else {
        const res = await axios.post("/api/notifications", notifData);
        const saved = res.data;
        setNotifications((prev) => [
          {
            id: saved._id,
            type: "info",
            title: saved.title,
            message: saved.message,
            time: new Date(saved.createdAt).toLocaleString(),
            read: false,
            recipients: saved.recipients,
          },
          ...prev,
        ]);
      }

      setNewTitle("");
      setNewMessage("");
      setRecipient("all");
      setEditId(null);
    } catch (err) {
      console.error("Error adding/updating notification:", err);
    }
  };

  const deleteNotification = async (id) => {
    try {
      await axios.delete(`/api/notifications/${id}`);
      setNotifications((prev) => prev.filter((n) => n.id !== id));
      if (selected && selected.id === id) setSelected(null);
    } catch (err) {
      console.error("Error deleting notification:", err);
    }
  };

  const editNotification = (id) => {
    const toEdit = notifications.find((n) => n.id === id);
    if (toEdit) {
      setNewTitle(toEdit.title);
      setNewMessage(toEdit.message);
      if (toEdit.recipients.length === 0) {
        setRecipient("all");
      } else {
        setRecipient(toEdit.recipients[0]);
      }
      setEditId(id);
    }
  };

  const markAsRead = (id) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    );
  };

  const getRecipientName = (recipients) => {
    if (!recipients || recipients.length === 0) return "All Employees";
    const emp = employees.find((e) => e._id === recipients[0]);
    return emp ? emp.name : "Unknown";
  };

  const filtered =
    filter === "all"
      ? notifications
      : notifications.filter((n) => n.type === filter);

  return (
    <div className="notifications-container">
      <h2 className="section-title">📢 Notifications</h2>

      {/* Form */}
      <div className="send-form">
        <select
          value={recipient}
          onChange={(e) => setRecipient(e.target.value)}
          style={{ color: "black" }}
        >
          <option value="all">Send to All</option>
          {employees.map((emp) => (
            <option key={emp._id} value={emp._id}>
              {emp.name}
            </option>
          ))}
        </select>

        <input
          type="text"
          placeholder="Title"
          value={newTitle}
          onChange={(e) => setNewTitle(e.target.value)}
        />
        <input
          type="text"
          placeholder="Message"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
        />
        <button onClick={addNotification}>
          {editId ? "Update" : "Send"}
        </button>
      </div>

      {/* Filter Buttons */}
      <div className="filter-buttons">
        {["all", "info", "success", "alert"].map((f) => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={filter === f ? "active" : ""}
          >
            {f.charAt(0).toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      <Particles
        className="particles"
        id="tsparticles"
        init={particlesInit}
        options={{
          background: { color: { value: "transparent" } },
          fpsLimit: 60,
          particles: {
            color: {
              value: ["#6a0572", "#a83279", "#4b0082", "#7b2cbf", "#3c1053"],
            },
            links: {
              color: "#6a0572",
              distance: 120,
              enable: true,
              opacity: 0.6,
              width: 1.4,
            },
            move: { enable: true, speed: 0.8 },
            number: { value: 60 },
            opacity: { value: 0.6 },
            shape: { type: "circle" },
            size: { value: { min: 2, max: 5 } },
          },
          interactivity: {
            events: { onHover: { enable: true, mode: "repulse" } },
            modes: { repulse: { distance: 100, duration: 0.4 } },
          },
          detectRetina: true,
        }}
      />

      {loading ? (
        <p>Loading notifications...</p>
      ) : (
        <div className="notifications-list">
          {filtered.map((notif) => (
            <div
              key={notif.id}
              className={`notification-card ${notif.type} ${
                notif.read ? "read" : ""
              }`}
            >
              <div
                className="icon-container"
                onClick={() => setSelected(notif)}
              >
                {getIcon(notif.type)}
              </div>
              <div className="content" onClick={() => setSelected(notif)}>
                <h4 className="title">{notif.title}</h4>
                <p className="message">
                  {notif.message.length > 40
                    ? notif.message.slice(0, 40) + "..."
                    : notif.message}
                </p>
                <small className="recipient">
                  👤 Sent to: {getRecipientName(notif.recipients)}
                </small>
                <span className="time">{notif.time}</span>
              </div>
              <div className="actions">
                {!notif.read && (
                  <button
                    className="mark-btn"
                    onClick={() => markAsRead(notif.id)}
                  >
                    Mark as Read
                  </button>
                )}
                <button
                  className="edit-btn sss"
                  onClick={() => editNotification(notif.id)}
                >
                  <FaEdit />
                </button>
                <button
                  className="delete-btn"
                  onClick={() => deleteNotification(notif.id)}
                >
                  <FaTrash />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal */}
      <Modal
        isOpen={!!selected}
        onRequestClose={() => setSelected(null)}
        className="modal"
        overlayClassName="modal-overlay"
      >
        {selected && (
          <div className="modal-content">
            <span className="close-btn" onClick={() => setSelected(null)}>
              &times;
            </span>
            <div className="modal-icon">{getIcon(selected.type)}</div>
            <h3>{selected.title}</h3>
            <p>{selected.message}</p>
            <small>{selected.time}</small>
            <br />
            <small>
              👤 Sent to: {getRecipientName(selected.recipients)}
            </small>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default Notifications;
