import React, { useState, useEffect } from 'react';
import './Attendance.css';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import { Bar, Pie } from 'react-chartjs-2';
import {
  FaUserCheck, FaCalendarAlt, FaFileExport,
  FaPlusCircle, FaClock, FaUserCircle
} from 'react-icons/fa';
import {
  Chart as ChartJS, ArcElement, Tooltip,
  Legend, BarElement, CategoryScale, LinearScale
} from 'chart.js';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import Particles from 'react-tsparticles';
import { loadSlim } from 'tsparticles-slim';
import axios from "../Https/Axios";

ChartJS.register(ArcElement, Tooltip, Legend, BarElement, CategoryScale, LinearScale);

const Attendance = () => {
  const [date, setDate] = useState(new Date());
  const [logs, setLogs] = useState([]);
  const [message, setMessage] = useState('');

  const formattedDate = date.toISOString().split('T')[0];
  const today = new Date().toISOString().split('T')[0];

  const particlesInit = async (engine) => {
    await loadSlim(engine);
  };

  const fetchAttendanceLogs = async () => {
    try {
      const response = await axios.get('/api/attendances/all');
      const cleanedData = (response.data || []).map(log => ({
        ...log,
        name: log.employeeId?.name || 'Unnamed User',
        date: log.date,
        status: log.status?.charAt(0).toUpperCase() + log.status?.slice(1), // e.g., "present" => "Present"
        checkIn: log.checkIn ? new Date(log.checkIn).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 'N/A',
        checkOut: log.checkOut ? new Date(log.checkOut).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 'N/A',
        streak: log.streak || 0
      }));
      setLogs(cleanedData);
    } catch (error) {
      console.error('Error fetching attendance data:', error);
    }
  };

  useEffect(() => {
    fetchAttendanceLogs();
  }, []);

  const handleManualMark = () => {
    const newLog = {
      id: logs.length + 1,
      name: 'New Employee',
      date: formattedDate,
      status: 'Present',
      checkIn: '09:30 AM',
      checkOut: '05:30 PM',
      streak: 1
    };
    setLogs([...logs, newLog]);
    setMessage('✅ Attendance marked manually!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleExport = async () => {
    const input = document.getElementById('attendance-section');
    if (!input) return;

    const canvas = await html2canvas(input, { scale: 2 });
    const imgData = canvas.toDataURL('image/png');

    const pdf = new jsPDF('p', 'mm', 'a4');
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const imgProps = pdf.getImageProperties(imgData);
    const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save('attendance_report.pdf');
  };

  const filteredLogs = logs.filter(log => log.date === formattedDate);
  const presentCount = logs.filter(log => log.status === 'Present').length;
  const absentCount = logs.filter(log => log.status === 'Absent').length;

  const pieData = {
    labels: ['Present', 'Absent'],
    datasets: [{
      label: 'Attendance',
      data: [presentCount, absentCount],
      backgroundColor: ['#7ae582', '#f67280'],
      borderWidth: 1
    }]
  };

  const barData = {
    labels: logs.map(log => log.name),
    datasets: [
      {
        label: 'Attendance Count',
        data: logs.map(log => (log.status === 'Present' ? 1 : 0)),
        backgroundColor: '#ff8ba7'
      }
    ]
  };

  const getInitials = (name) => {
    if (!name) return 'NA';
    return name.split(' ').map(n => n[0]).join('').toUpperCase();
  };

  const getDayOfWeek = (dateStr) => new Date(dateStr).toLocaleDateString('en-US', { weekday: 'long' });

  return (
    <div className="attendance-container">
      <h2 className="attendance-heading">📅 Attendance Management</h2>

      {message && <div className="success-toast">{message}</div>}

      <div id="attendance-section">
        <div className="calendar-section">
          <Calendar onChange={setDate} value={date} />
        </div>

        <div className="right-panel">
          <div className="filters">
            <button className="manual-btn" onClick={handleManualMark}>
              <FaPlusCircle /> Mark Manually
            </button>
            <button className="export-btn" onClick={handleExport}>
              <FaFileExport /> Export Report
            </button>
          </div>

          <Particles
            className="particles"
            id="tsparticles"
            init={particlesInit}
            options={{
              background: { color: { value: 'transparent' } },
              fpsLimit: 60,
              particles: {
                color: {
                  value: ['#6a0572', '#a83279', '#4b0082', '#7b2cbf', '#3c1053'],
                },
                links: {
                  color: '#6a0572',
                  distance: 120,
                  enable: true,
                  opacity: 0.6,
                  width: 1.4,
                },
                move: { enable: true, speed: 0.8 },
                number: { value: 60 },
                opacity: { value: 0.6 },
                shape: { type: 'circle' },
                size: { value: { min: 2, max: 5 } },
              },
              interactivity: {
                events: {
                  onHover: { enable: true, mode: 'repulse' },
                },
                modes: {
                  repulse: { distance: 100, duration: 0.4 },
                },
              },
              detectRetina: true,
            }}
          />

          <div className="logs">
            {filteredLogs.length ? (
              filteredLogs.map((log, index) => (
                <div key={index} className={`log-card ${log.status.toLowerCase()} ${log.date === today ? 'today-highlight' : ''}`}>
                  <div className="avatar">
                    <FaUserCircle className="avatar-icon" />
                    <span>{getInitials(log.name)}</span>
                  </div>
                  <h4>{log.name}</h4>
                  <p><FaCalendarAlt /> {getDayOfWeek(log.date)}, {log.date}</p>
                  {log.status === 'Present' && (
                    <div className="time-info">
                      <p title="Check-In Time"><FaClock /> In: {log.checkIn}</p>
                      <p title="Check-Out Time"><FaClock /> Out: {log.checkOut}</p>
                    </div>
                  )}
                  <span className="status">{log.status}</span>
                  {log.status === 'Present' && log.streak > 0 && (
                    <div className="streak-badge">🔥 {log.streak}-day streak</div>
                  )}
                </div>
              ))
            ) : (
              <p className="no-results">No attendance logs found.</p>
            )}
          </div>

          <div className="charts-section">
            <div className="chart-card">
              <h3>Attendance Pie</h3>
              <Pie data={pieData} />
            </div>
            <div className="chart-card">
              <h3>Attendance Bar</h3>
              <Bar data={barData} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Attendance;
