import React, { useState } from 'react';
import './Sidebar.css';
import { NavLink } from 'react-router-dom';

// Icons
import { FaTachometerAlt } from 'react-icons/fa'; // Dashboard
import { FaUsers } from 'react-icons/fa'; // Employee Management
import { FaTasks } from 'react-icons/fa'; // Projects
import { FaCalendarCheck } from 'react-icons/fa'; // Attendance
import { FaBell } from 'react-icons/fa'; // Notifications
import { FaPlaneDeparture } from 'react-icons/fa'; // Leave Management
import { FaChartBar } from 'react-icons/fa'; // Reports
import { FaBug } from 'react-icons/fa'; // Reported Issues
import { FaBars, FaTimes } from 'react-icons/fa'; // Toggle

const Sidebar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const toggleSidebar = () => setIsOpen(!isOpen);

  return (
    <>
      {/* Hamburger toggle button visible only on small screens */}
      <button className="sidebar-toggle-btn" onClick={toggleSidebar}>
        {isOpen ? <FaTimes /> : <FaBars />}
      </button>

      <aside className={`sidebar ${isOpen ? 'open' : ''}`}>
        <h2 className="sidebar-title"> Menu</h2>
        <ul className="sidebar-menu">
          <NavLink to="/dashboard" className="sidebar-item" activeclassname="active" onClick={() => setIsOpen(false)}>
            <FaTachometerAlt className="icon" /> Dashboard
          </NavLink>
          <NavLink to="/employee" className="sidebar-item" activeclassname="active" onClick={() => setIsOpen(false)}>
            <FaUsers className="icon" /> Employees
          </NavLink>
          <NavLink to="/projects" className="sidebar-item" activeclassname="active" onClick={() => setIsOpen(false)}>
            <FaTasks className="icon" /> Projects
          </NavLink>
          <NavLink to="/attendance" className="sidebar-item" activeclassname="active" onClick={() => setIsOpen(false)}>
            <FaCalendarCheck className="icon" /> Attendance
          </NavLink>
          <NavLink to="/notifications" className="sidebar-item" activeclassname="active" onClick={() => setIsOpen(false)}>
            <FaBell className="icon" /> Alerts
          </NavLink>
          <NavLink to="/leavemanagement" className="sidebar-item" activeclassname="active" onClick={() => setIsOpen(false)}>
            <FaPlaneDeparture className="icon" /> Leave
          </NavLink>
          <NavLink to="/reports" className="sidebar-item" activeclassname="active" onClick={() => setIsOpen(false)}>
            <FaChartBar className="icon" /> Insights
          </NavLink>
          <NavLink to="/problemreports" className="sidebar-item" activeclassname="active" onClick={() => setIsOpen(false)}>
            <FaBug className="icon" /> Issues
          </NavLink>
        </ul>
      </aside>
    </>
  );
};

export default Sidebar;
