import React from "react";
import "./Reports.css";
import { FaUserCheck, FaTasks, FaChartLine, FaFilePdf, FaFileExcel } from "react-icons/fa";
import Particles from 'react-tsparticles';
import { loadSlim } from 'tsparticles-slim';


const Reports = () => {
  const handleExport = (type) => {
    alert(`Exporting as ${type}... (You can integrate real logic here)`);
  };
const particlesInit = async (engine) => {
  await loadSlim(engine);
};

  return (
    <div className="reports-container">
      <h1 className="reports-title">📊 Reports Dashboard</h1>

      <div className="reports-grid">
        <div className="report-card">
          <FaUserCheck className="report-icon" />
          <h2>Attendance Reports</h2>
          <p>Track employee attendance with detailed logs and monthly summaries.</p>
        </div>

        <div className="report-card">
          <FaTasks className="report-icon" />
          <h2>Project Reports</h2>
          <p>View all ongoing, completed, and delayed projects with timelines.</p>
        </div>
<Particles
  className="particles"
  id="tsparticles"
  init={particlesInit}
  options={{
    background: { color: { value: 'transparent' } },
    fpsLimit: 60,
    particles: {
      color: {
        value: ['#6a0572', '#a83279', '#4b0082', '#7b2cbf', '#3c1053'],
      },
      links: {
        color: '#6a0572',
        distance: 120,
        enable: true,
        opacity: 0.6,
        width: 1.4,
      },
      move: { enable: true, speed: 0.8 },
      number: { value: 60 },
      opacity: { value: 0.6 },
      shape: { type: 'circle' },
      size: { value: { min: 2, max: 5 } },
    },
    interactivity: {
      events: {
        onHover: { enable: true, mode: 'repulse' },
      },
      modes: {
        repulse: { distance: 100, duration: 0.4 },
      },
    },
    detectRetina: true,
  }}
/>

        <div className="report-card">
          <FaChartLine className="report-icon" />
          <h2>Performance Reports</h2>
          <p>Evaluate employee performance based on key metrics and goals.</p>
        </div>
      </div>

      <div className="export-section">
        <h3>📤 Export Reports</h3>
        <button className="export-btn pdf" onClick={() => handleExport("PDF")}>
          <FaFilePdf /> Export as PDF
        </button>
        <button className="export-btn excel" onClick={() => handleExport("Excel")}>
          <FaFileExcel /> Export as Excel
        </button>
      </div>

      <div className="extra-section">
        <h3>✨ Insights</h3>
        <ul>
          <li>⭐ Top Performer of the Month</li>
          <li>📅 Most Active Team</li>
          <li>🕒 Avg. Work Hours This Week</li>
          <li>🏆 Team Productivity Score</li>
        </ul>
      </div>
    </div>
  );
};

export default Reports;
