import React, { useState, useEffect } from "react";
import axios from "../Https/Axios";
import "./LeaveManagement.css";
import {
  FaUserCircle, FaCheck, FaTimes, FaSearch, FaCalendarAlt,
  FaFilter, FaCommentDots
} from "react-icons/fa";
import Particles from 'react-tsparticles';
import { loadSlim } from 'tsparticles-slim';

const particlesInit = async (engine) => {
  await loadSlim(engine);
};

export default function LeaveManagement() {
  const [leaves, setLeaves] = useState([]);
  const [filter, setFilter] = useState("");
  const [remarkModal, setRemarkModal] = useState(null);
  const [adminRemark, setAdminRemark] = useState("");

  useEffect(() => {
    fetchLeaves();
  }, []);

  const fetchLeaves = () => {
    axios.get("/api/leaves")
      .then(response => {
        // Map adminRemarks to adminRemark for frontend
        const mappedLeaves = response.data.map(leave => ({
          ...leave,
          adminRemark: leave.adminRemarks || ""  // fallback in case it's undefined
        }));
        setLeaves(mappedLeaves);
      })
      .catch(error => {
        console.error("Error fetching leave data:", error);
      });
  };

  const handleStatusChange = (id, status) => {
    axios.put(`/api/leaves/${id}`, { status })
      .then(() => {
        setLeaves(prev =>
          prev.map(leave =>
            leave._id === id ? { ...leave, status } : leave
          )
        );
      })
      .catch(error => {
        console.error("Error updating status:", error);
      });
  };

  const handleSubmitRemark = () => {
    axios.put(`/api/leaves/${remarkModal}`, {
      adminRemarks: adminRemark,  // API ko wahi key bhejna
    })
      .then(() => {
        setLeaves(prev =>
          prev.map(leave =>
            leave._id === remarkModal ? { ...leave, adminRemark } : leave
          )
        );
        setAdminRemark("");
        setRemarkModal(null);
      })
      .catch(error => {
        console.error("Error adding remark:", error);
      });
  };

  const filteredLeaves = leaves.filter((leave) =>
    (leave.employeeId?.name || "").toLowerCase().includes(filter.toLowerCase()) ||
    (leave.status || "").toLowerCase().includes(filter.toLowerCase()) ||
    (leave.fromDate || "").includes(filter)
  );

  return (
    <div className="leave-container">
      <h2>🌸 Leave Management Panel</h2>
      <div className="leave-filters">
        <FaSearch />
        <input
          type="text"
          placeholder="Search by employee, date or status..."
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
        />
        <FaFilter className="filter-icon" />
      </div>

      <Particles
        className="particles"
        id="tsparticles"
        init={particlesInit}
        options={{
          background: { color: { value: 'transparent' } },
          fpsLimit: 60,
          particles: {
            color: {
              value: ['#6a0572', '#a83279', '#4b0082', '#7b2cbf', '#3c1053'],
            },
            links: {
              color: '#6a0572',
              distance: 120,
              enable: true,
              opacity: 0.6,
              width: 1.4,
            },
            move: { enable: true, speed: 0.8 },
            number: { value: 60 },
            opacity: { value: 0.6 },
            shape: { type: 'circle' },
            size: { value: { min: 2, max: 5 } },
          },
          interactivity: {
            events: {
              onHover: { enable: true, mode: 'repulse' },
            },
            modes: {
              repulse: { distance: 100, duration: 0.4 },
            },
          },
          detectRetina: true,
        }}
      />

      <div className="leave-list">
        {filteredLeaves.map((leave) => (
          <div className="leave-card" key={leave._id}>
            <FaUserCircle className="user-icon" />
            <div className="leave-info">
              <h3>{leave.employeeId?.name || "Unknown"}</h3>
              <p><FaCalendarAlt /> {new Date(leave.fromDate).toLocaleDateString()} to {new Date(leave.toDate).toLocaleDateString()}</p>
              <p>Reason: {leave.reason}</p>
              <p>Status: <span className={`status ${leave.status.toLowerCase()}`}>{leave.status}</span></p>
              {leave.adminRemark && <p><strong>Remark:</strong> {leave.adminRemark}</p>}
            </div>
            <div className="leave-actions">
              <button
                className="approve-btn"
                onClick={() => handleStatusChange(leave._id, "Approved")}
              >
                <FaCheck /> Approve
              </button>
              <button
                className="reject-btn"
                onClick={() => handleStatusChange(leave._id, "Rejected")}
              >
                <FaTimes /> Reject
              </button>
              <button
                className="remark-btn"
                onClick={() => {
                  setAdminRemark(leave.adminRemark || "");
                  setRemarkModal(leave._id);
                }}
              >
                <FaCommentDots /> Add Remark
              </button>
            </div>
          </div>
        ))}
      </div>

      {remarkModal && (
        <div className="remark-modal">
          <div className="modal-content">
            <h3>Admin Remark</h3>
            <textarea
              placeholder="Write your remark here..."
              value={adminRemark}
              onChange={(e) => setAdminRemark(e.target.value)}
            />
            <button onClick={handleSubmitRemark}>Submit Remark</button>
            <button onClick={() => setRemarkModal(null)}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}
