import React, { useState, useEffect } from "react";
import axios from "../Https/Axios";
import { Plus, Edit, Trash2, UserPlus2, X } from "lucide-react";
import { motion } from "framer-motion";
import Particles from "react-tsparticles";
import { loadSlim } from "tsparticles-slim";
import "./Projects.css";

const API_URL = "/api/Projects";
const EMPLOYEE_API = "/api/employees";

const Projects = () => {
  const [projects, setProjects] = useState([]);
  const [employees, setEmployees] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [editModal, setEditModal] = useState(false);
  const [newProject, setNewProject] = useState({
    name: "",
    description: "",
    startDate: "",
    endDate: "",
    employees: [],
  });

  const [selectedProjectId, setSelectedProjectId] = useState(null);

  const fetchProjects = async () => {
    try {
      const res = await axios.get(API_URL);
      setProjects(res.data);
    } catch (err) {
      console.error("Error fetching projects:", err);
    }
  };

  const fetchEmployees = async () => {
    try {
      const res = await axios.get(EMPLOYEE_API);
      setEmployees(res.data);
    } catch (err) {
      console.error("Error fetching employees:", err);
    }
  };

  const createProject = async () => {
    try {
      const res = await axios.post(API_URL, newProject);
      setProjects((prev) => [...prev, res.data]);
      resetForm();
      setShowModal(false);
    } catch (err) {
      console.error("Error creating project:", err);
    }
  };

  const deleteProject = async (id) => {
    try {
      await axios.delete(`${API_URL}/${id}`);
      setProjects((prev) => prev.filter((p) => p._id !== id));
    } catch (err) {
      console.error("Error deleting project:", err);
    }
  };

  const updateProject = async () => {
    try {
      await axios.put(`${API_URL}/${selectedProjectId}`, newProject);
      fetchProjects();
      resetForm();
      setEditModal(false);
    } catch (err) {
      console.error("Error updating project:", err);
    }
  };

  const handleEdit = (project) => {
    setNewProject({
      name: project.name,
      description: project.description,
      startDate: project.startDate?.substr(0, 10) || "",
      endDate: project.endDate?.substr(0, 10) || "",
      employees: project.employees || [],
    });
    setSelectedProjectId(project._id);
    setEditModal(true);
  };

  const resetForm = () => {
    setNewProject({
      name: "",
      description: "",
      startDate: "",
      endDate: "",
      employees: [],
    });
    setSelectedProjectId(null);
  };

  useEffect(() => {
    fetchProjects();
    fetchEmployees();
  }, []);

  const particlesInit = async (engine) => {
    await loadSlim(engine);
  };

  const getEmployeeNameById = (id) => {
    const emp = employees.find((e) => e._id === id);
    return emp?.name || "Unknown";
  };

  return (
    <div className="projects-page">
      <section className="projects-section">
        <motion.h2
          initial={{ y: -30, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.6 }}
        >
          🚀 Manage Projects
        </motion.h2>

        <div className="projects-actions">
          <button className="create-btn" onClick={() => setShowModal(true)}>
            <Plus size={20} /> Create Project
          </button>
        </div>

        <Particles
          className="particles"
          id="tsparticles"
          init={particlesInit}
          options={{
            background: { color: { value: "transparent" } },
            fpsLimit: 60,
            particles: {
              color: {
                value: ["#6a0572", "#a83279", "#4b0082", "#7b2cbf", "#3c1053"],
              },
              links: {
                color: "#6a0572",
                distance: 120,
                enable: true,
                opacity: 0.6,
                width: 1.4,
              },
              move: { enable: true, speed: 0.8 },
              number: { value: 60 },
              opacity: { value: 0.6 },
              shape: { type: "circle" },
              size: { value: { min: 2, max: 5 } },
            },
            interactivity: {
              events: { onHover: { enable: true, mode: "repulse" } },
              modes: { repulse: { distance: 100, duration: 0.4 } },
            },
            detectRetina: true,
          }}
        />

        <div className="projects-grid-scrollable">
          <div className="projects-grid">
            {projects.map((project) => (
              <motion.div
                key={project._id}
                initial={{ scale: 0.95, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                transition={{ duration: 0.4 }}
              >
                <div className="project-card">
                  <div className="card-header">
                    <h3>{project.name}</h3>
                    <div className="card-icons">
                      <Edit
                        className="icon edit"
                        title="Edit"
                        onClick={() => handleEdit(project)}
                      />
                      <Trash2
                        className="icon delete"
                        title="Delete"
                        onClick={() => deleteProject(project._id)}
                      />
                    </div>
                  </div>

                  <p className="description">{project.description}</p>

                  <div className="dates">
                    <strong>Start:</strong>{" "}
                    {project.startDate
                      ? new Date(project.startDate).toLocaleDateString()
                      : "N/A"}
                    <br />
                    <strong>End:</strong>{" "}
                    {project.endDate
                      ? new Date(project.endDate).toLocaleDateString()
                      : "N/A"}
                  </div>

                 <div>
  <strong>Assigned:</strong>{" "}
  {project.employees.length > 0
    ? project.employees.map((emp) => emp.name).join(", ")
    : "No one yet"}
</div>

                </div>
              </motion.div>
            ))}
          </div>
        </div>

        {(showModal || editModal) && (
          <div className="modal-overlay">
            <motion.div
              className="modal-content"
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 0.4 }}
            >
              <button
                className="modal-close-btn"
                onClick={() => {
                  setShowModal(false);
                  setEditModal(false);
                  resetForm();
                }}
              >
                <X size={20} />
              </button>
              <h3 className="modal-heading">
                {editModal ? "✏️ Edit Project" : "🎉 Create New Project"}
              </h3>

              <div className="container">
                <div className="row mb-3">
                  <div className="col-md-12">
                    <input
                      type="text"
                      placeholder="Project Title"
                      value={newProject.name}
                      onChange={(e) =>
                        setNewProject({ ...newProject, name: e.target.value })
                      }
                      className="form-control"
                    />
                  </div>
                </div>

                <div className="row mb-3">
                  <div className="col-md-12">
                    <textarea
                      placeholder="Description"
                      value={newProject.description}
                      onChange={(e) =>
                        setNewProject({
                          ...newProject,
                          description: e.target.value,
                        })
                      }
                      className="form-control"
                    />
                  </div>
                </div>

                <div className="row mb-3">
                  <div className="col-md-6">
                    <label className="form-label">Start Date</label>
                    <input
                      type="date"
                      className="form-control"
                      value={newProject.startDate}
                      onChange={(e) =>
                        setNewProject({
                          ...newProject,
                          startDate: e.target.value,
                        })
                      }
                    />
                  </div>

                  <div className="col-md-6">
                    <label className="form-label">End Date</label>
                    <input
                      type="date"
                      className="form-control"
                      value={newProject.endDate}
                      onChange={(e) =>
                        setNewProject({
                          ...newProject,
                          endDate: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>

                <div className="row mb-4">
                  <div className="col-md-12">
                    <label className="form-label">Assign Employees</label>
                    <select
                      multiple
                      className="form-select"
                      value={newProject.employees}
                      onChange={(e) =>
                        setNewProject({
                          ...newProject,
                          employees: Array.from(
                            e.target.selectedOptions,
                            (opt) => opt.value
                          ),
                        })
                      }
                    >
                      {employees.map((emp) => (
                        <option key={emp._id} value={emp._id}>
                          {emp.name}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

               <div className="d-flex justify-content-center gap-3">
  {editModal ? (
    <button className="btn btn-primary " onClick={updateProject}>
      Update Project
    </button>
  ) : (
    <button className="btn btn-primary" onClick={createProject}>
      Save Project
    </button>
  )}
  <button
    onClick={() => {
      setShowModal(false);
      setEditModal(false);
      resetForm();
    }}
    className="btn btn-secondary bbb"
  >
    Cancel
  </button>
</div>

              </div>
            </motion.div>
          </div>
        )}
      </section>
    </div>
  );
};

export default Projects;
