import React, { useState, useEffect } from 'react';
import axios from "../Https/Axios";
import './ProblemReports.css';
import Particles from 'react-tsparticles';
import { loadSlim } from 'tsparticles-slim';


const ProblemReports = () => {
  const [problems, setProblems] = useState([]);
  const [filter, setFilter] = useState('All');

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchEmployeeName = async (id) => {
    try {
      const res = await axios.get(`/api/employees/${id}`);
      return res.data.name;
    } catch (error) {
      console.error('Error fetching employee name:', error);
      return 'Unknown';
    }
  };

  const fetchProblems = async () => {
    try {
      const response = await axios.get('/api/reports');
      const reports = response.data;

      // Fetch all employee names in parallel
      const reportsWithNames = await Promise.all(
        reports.map(async (report) => {
          const employeeName = await fetchEmployeeName(report.employeeId);
          return { ...report, employeeName };
        })
      );

      setProblems(reportsWithNames);
    } catch (error) {
      console.error('Error fetching problems:', error);
    }
  };

  const handleStatusChange = async (id, newStatus) => {
    try {
      const updatedProblem = problems.find(p => p._id === id);
      const updatedData = { ...updatedProblem, status: newStatus };
      delete updatedData.employeeName; // Remove extra field before sending

      await axios.put(`/api/reports/${id}`, updatedData);

      setProblems(prev =>
        prev.map(p => (p._id === id ? { ...p, status: newStatus } : p))
      );
    } catch (error) {
      console.error('Error updating status:', error);
    }
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`/api/reports/${id}`);
      setProblems(prev => prev.filter(p => p._id !== id));
    } catch (error) {
      console.error('Error deleting problem:', error);
    }
  };

  const filteredProblems =
    filter === 'All' ? problems : problems.filter(p => p.status === filter);

  const particlesInit = async (engine) => {
    await loadSlim(engine);
  };

  return (
    <div className="problem-reports-container">
      <div className="problem-reports-header">
        <h1>🛠️ Problem Reports</h1>
        <div className="filter-box">
          <label>Status:</label>
          <select onChange={e => setFilter(e.target.value)} value={filter}>
            <option value="All">All</option>
            <option value="Open">Open</option>
            <option value="In Progress">In Progress</option>
            <option value="Resolved">Resolved</option>
          </select>
        </div>
      </div>

      <Particles
        className="particles"
        id="tsparticles"
        init={particlesInit}
        options={{
          background: { color: { value: 'transparent' } },
          fpsLimit: 60,
          particles: {
            color: {
              value: ['#6a0572', '#a83279', '#4b0082', '#7b2cbf', '#3c1053'],
            },
            links: {
              color: '#6a0572',
              distance: 120,
              enable: true,
              opacity: 0.6,
              width: 1.4,
            },
            move: { enable: true, speed: 0.8 },
            number: { value: 60 },
            opacity: { value: 0.6 },
            shape: { type: 'circle' },
            size: { value: { min: 2, max: 5 } },
          },
          interactivity: {
            events: {
              onHover: { enable: true, mode: 'repulse' },
            },
            modes: {
              repulse: { distance: 100, duration: 0.4 },
            },
          },
          detectRetina: true,
        }}
      />

      {/* Problem Cards */}
      <div className="problem-cards">
        {filteredProblems.map(problem => (
          <div key={problem._id} className="problem-card">
            <div className="problem-title">{problem.title}</div>
            <div className="problem-description">{problem.description}</div>
            <div className="problem-employee"><strong>By:</strong> {problem.employeeId.name}</div>
            <div className={`status-badge ${problem.status.replace(' ', '').toLowerCase()}`}>
              {problem.status}
            </div>
            <div className="progress-container">
              <div className={`progress-bar ${problem.status.replace(' ', '').toLowerCase()}`}></div>
            </div>
            <div className="status-control">
              <label>Update:</label>
              <select
                value={problem.status}
                onChange={e => handleStatusChange(problem._id, e.target.value)}
              >
                <option value="Open">Open</option>
                <option value="In Progress">In Progress</option>
                <option value="Resolved">Resolved</option>
              </select>
            </div>
           <button
  style={{
    color: "black",
    backgroundColor: "white",
    padding: "8px 12px",
    border: "1px solid #ccc",
    borderRadius: "4px",
    cursor: "pointer"
  }}
  onClick={() => handleDelete(problem._id)}
>
  Delete
</button>


          </div>
        ))}
      </div>
    </div>
  );
};

export default ProblemReports;
